1	package edgefleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"time"
8	)
9	
10	// Heartbeat is one telemetry record reported by a node.
11	//
12	// JSON input uses snake_case field names:
13	//
14	//	node          string   node id (required, non-empty)
15	//	seq           integer  sequence number (required, > 0)
16	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00 (required)
17	//	version       string   version (required, non-empty)
18	//	height        integer  block height (required, >= 0)
19	//	missed        integer  cumulative missed duties (required, >= 0)
20	type Heartbeat struct {
21		NodeID      string    `json:"node"`
22		Seq         int64     `json:"seq"`
23		CollectedAt time.Time `json:"collected_at"`
24		Version     string    `json:"version"`
25		Height      int64     `json:"height"`
26		Missed      int64     `json:"missed"`
27	}
28	
29	// heartbeatFields enumerates every field that must be explicitly provided.
30	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
31	
32	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
33	// the moment the platform received the batch; a collection time later than
34	// receive time is rejected.
35	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
36		if h.NodeID == "" {
37			return fmt.Errorf("node id is empty")
38		}
39		if h.Seq <= 0 {
40			return fmt.Errorf("seq must be a positive integer, got %d", h.Seq)
41		}
42		if h.Version == "" {
43			return fmt.Errorf("version is empty")
44		}
45		if h.Height < 0 {
46			return fmt.Errorf("height must be >= 0, got %d", h.Height)
47		}
48		if h.Missed < 0 {
49			return fmt.Errorf("missed must be >= 0, got %d", h.Missed)
50		}
51		if h.CollectedAt.IsZero() {
52			return fmt.Errorf("collected_at is missing or invalid")
53		}
54		if h.CollectedAt.After(receiveTime) {
55			return fmt.Errorf("collected_at %s is later than receive time %s",
56				h.CollectedAt.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
57		}
58		return nil
59	}
60	
61	// Equal reports whether two records are the same telemetry. Collection times
62	// are compared as instants, so the same moment expressed in different
63	// timezones compares equal.
64	func (h Heartbeat) Equal(o Heartbeat) bool {
65		return h.NodeID == o.NodeID &&
66			h.Seq == o.Seq &&
67			h.Version == o.Version &&
68			h.Height == o.Height &&
69			h.Missed == o.Missed &&
70			h.CollectedAt.Equal(o.CollectedAt)
71	}
72	
73	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
74	// be explicitly provided; missing or unknown fields are rejected with a
75	// specific reason.
76	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
77		var raw []json.RawMessage
78		if err := json.Unmarshal(data, &raw); err != nil {
79			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
80		}
81		if len(raw) == 0 {
82			return nil, fmt.Errorf("no heartbeat records provided")
83		}
84		records := make([]Heartbeat, 0, len(raw))
85		for i, r := range raw {
86			h, err := parseOneHeartbeat(r, receiveTime)
87			if err != nil {
88				return nil, fmt.Errorf("record %d: %w", i+1, err)
89			}
90			records = append(records, h)
91		}
92		return records, nil
93	}
94	
95	// rejectNull reports an error when a required field's JSON value is null.
96	// A null value means the node did not report the field, which must not be
97	// silently saved as the zero value.
98	func rejectNull(raw json.RawMessage, field string) error {
99		if bytes.Equal(raw, []byte("null")) {
100			return fmt.Errorf("%s must not be null", field)
101		}
102		return nil
103	}
104	
105	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
106		// Walk the object with a streaming decoder so duplicate field names are
107		// detected. Field names are compared as the JSON string they represent:
108		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
109		// would silently keep only the last occurrence.
110		dec := json.NewDecoder(bytes.NewReader(raw))
111		tok, err := dec.Token()
112		if err != nil {
113			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
114		}
115		if d, ok := tok.(json.Delim); !ok || d != '{' {
116			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
117		}
118	
119		fields := make(map[string]json.RawMessage)
120		for dec.More() {
121			keyTok, err := dec.Token()
122			if err != nil {
123				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
124			}
125			key, ok := keyTok.(string)
126			if !ok {
127				return Heartbeat{}, fmt.Errorf("field name must be a string")
128			}
129			if _, exists := fields[key]; exists {
130				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
131			}
132			var val json.RawMessage
133			if err := dec.Decode(&val); err != nil {
134				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
135			}
136			fields[key] = val
137		}
138		// Consume the closing brace.
139		if _, err := dec.Token(); err != nil {
140			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
141		}
142	
143		for _, f := range heartbeatFields {
144			if _, ok := fields[f]; !ok {
145				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
146			}
147		}
148		for k := range fields {
149			if !containsString(heartbeatFields, k) {
150				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
151			}
152		}
153	
154		var h Heartbeat
155	
